  void spells(LinearLayout c){c.addView(t("Separate casting tracks keep Cleric, Magic-User, Druid, Illusionist, or house-ruled multiclass spell use independent.",14,MUT,false));JSONArray a=tracks();for(int i=0;i<a.length();i++){JSONObject tr=a.optJSONObject(i);if(tr==null)continue;final int ti=i;LinearLayout k=card(tr.optString("class","Caster")+" • class level "+tr.optInt("level",1));JSONArray sp=tr.optJSONArray("spells");if(sp==null)sp=new JSONArray();for(int j=0;j<sp.length();j++){JSONObject o=sp.optJSONObject(j);if(o==null)continue;final int sj=j;boolean used=o.optBoolean("used");LinearLayout r=new LinearLayout(this);TextView n=t("L"+o.optInt("level",1)+"  "+o.optString("name","Spell")+(used?"  [USED]":""),15,used?MUT:TXT,!used);r.addView(n,new LinearLayout.LayoutParams(0,-2,1));Button u=b(used?"Restore":"Use");u.setOnClickListener(v->{try{o.put("used",!o.optBoolean("used"));save(a);show("Spells");}catch(Exception e){}});r.addView(u);Button d=b("×");d.setOnClickListener(v->{tr.optJSONArray("spells").remove(sj);save(a);show("Spells");});r.addView(d);k.addView(r);}LinearLayout acts=new LinearLayout(this);Button add=b("+ Prepare");add.setOnClickListener(v->spellDialog(a,ti));acts.addView(add,new LinearLayout.LayoutParams(0,dp(48),1));Button rest=b("Rest / Restore All");rest.setOnClickListener(v->{JSONArray q=tr.optJSONArray("spells");for(int j=0;j<q.length();j++)try{q.getJSONObject(j).put("used",false);}catch(Exception e){}save(a);show("Spells");});acts.addView(rest,new LinearLayout.LayoutParams(0,dp(48),1));k.addView(acts);Button del=b("Remove casting track");del.setOnClickListener(v->{a.remove(ti);save(a);show("Spells");});k.addView(del);add(c,k);}Button addTrack=b("+ Add Casting Track");addTrack.setOnClickListener(v->trackDialog());add(c,addTrack);}
