  int roll(String s){Matcher m=Pattern.compile("(?i)^\\s*(\\d*)d(\\d+)(?:\\s*([+-])\\s*(\\d+))?\\s*$").matcher(s);if(!m.matches())throw new RuntimeException();int n=m.group(1).isEmpty()?1:Integer.parseInt(m.group(1)),d=Integer.parseInt(m.group(2)),v=0;for(int i=0;i<n;i++)v+=1+rng.nextInt(d);if(m.group(3)!=null)v+=(m.group(3).equals("-")?-1:1)*Integer.parseInt(m.group(4));return v;}
